// so no delivery is final and a transient failure Naks — it must NOT read
// every delivery as final and Term on the first failure.
func TestNakOrTermZeroMaxDeliverNaks(t *testing.T) {
	p := Policy{NakDelay: testDelay, TermOnExhaustion: true} // MaxDeliver unset
	msg := delivered(1)

	got, err := p.NakOrTerm(msg)
	if err != nil {
		t.Fatalf("NakOrTerm: %v", err)
	}
	if got != OutcomeNak {
		t.Errorf("outcome = %q, want nak", got)
	}
	if msg.Termed {
		t.Error("termed on the first delivery with an unset MaxDeliver")
	}
}

// TestDelayForFlatByDefault pins zero-value compatibility: without a Factor
// the envelope stays flat at NakDelay for every delivery, exactly the
// pre-growth behavior.
func TestDelayForFlatByDefault(t *testing.T) {
	p := Policy{NakDelay: testDelay}
	for _, n := range []int{0, 1, 2, 5, 50} {
		if got := p.DelayFor(n); got != testDelay {
			t.Errorf("flat DelayFor(%d) = %v, want %v", n, got, testDelay)
		}
	}
}

// TestDelayForGrows covers the two envelopes the services actually run:
// entire-api's 1s doubling capped at 300s and entiredb's 5s doubling capped
// at 30s.
func TestDelayForGrows(t *testing.T) {
	for _, tc := range []struct {
		name string
		p    Policy
		want map[int]time.Duration
	}{
		{
			name: "1s doubling capped at 300s",
			p:    Policy{NakDelay: time.Second, Factor: 2, MaxDelay: 300 * time.Second},
			want: map[int]time.Duration{
				0: time.Second, 1: time.Second, 2: 2 * time.Second, 3: 4 * time.Second,
				9: 256 * time.Second, 10: 300 * time.Second, 20: 300 * time.Second,
			},
		},
		{
			name: "5s doubling capped at 30s",
			p:    Policy{NakDelay: 5 * time.Second, Factor: 2, MaxDelay: 30 * time.Second},
			want: map[int]time.Duration{
				1: 5 * time.Second, 2: 10 * time.Second, 3: 20 * time.Second,
				4: 30 * time.Second, 8: 30 * time.Second,
			},
		},
	} {
		for n, want := range tc.want {
			if got := tc.p.DelayFor(n); got != want {
				t.Errorf("%s: DelayFor(%d) = %v, want %v", tc.name, n, got, want)
			}
		}
	}
}

// TestDelayForSaturatesWithoutCap: uncapped growth must saturate rather than
// wrap negative — a negative NakWithDelay would redeliver immediately, the
// opposite of backing off.
func TestDelayForSaturatesWithoutCap(t *testing.T) {
	p := Policy{NakDelay: time.Hour, Factor: 10}
	if got := p.DelayFor(30); got != time.Duration(math.MaxInt64) {
		t.Errorf("uncapped DelayFor(30) = %v, want saturation at MaxInt64", got)
	}
	if got := p.DelayFor(30); got < 0 {
		t.Errorf("uncapped DelayFor(30) went negative: %v", got)
	}
}

// TestNakOrTermUsesGrownDelay: NakOrTerm must nak with the delay for THIS
// delivery's count from the message metadata, not the base delay.
func TestNakOrTermUsesGrownDelay(t *testing.T) {
	p := Policy{NakDelay: time.Second, Factor: 2, MaxDelay: 300 * time.Second, MaxDeliver: 8}
	msg := delivered(3)

	got, err := p.NakOrTerm(msg)
	if err != nil {
		t.Fatalf("NakOrTerm: %v", err)
	}
	if got != OutcomeNak {
		t.Errorf("outcome = %q, want nak", got)
	}
	if len(msg.NakDelays) != 1 || msg.NakDelays[0] != 4*time.Second {
		t.Errorf("NakDelays = %v, want one nak with the grown 4s delay", msg.NakDelays)
	}
}

// TestNakOrTermGrownDelayMissingMetadata: without metadata the delivery count
// is unknown; the policy naks with the base delay (first-delivery read).
func TestNakOrTermGrownDelayMissingMetadata(t *testing.T) {
	p := Policy{NakDelay: time.Second, Factor: 2, MaxDelay: 300 * time.Second}
	msg := &natsmsgtest.FakeMsg{MetaErr: errors.New("no metadata")}

	if _, err := p.NakOrTerm(msg); err != nil {
		t.Fatalf("NakOrTerm: %v", err)
	}
	if len(msg.NakDelays) != 1 || msg.NakDelays[0] != time.Second {
		t.Errorf("NakDelays = %v, want one nak with the base delay", msg.NakDelays)
	}
}

func TestNumDelivered(t *testing.T) {
	if got := NumDelivered(delivered(3)); got != 3 {
		t.Errorf("NumDelivered = %d, want 3", got)
	}
	if got := NumDelivered(&natsmsgtest.FakeMsg{MetaErr: errors.New("none")}); got != 0 {
		t.Errorf("NumDelivered without metadata = %d, want 0", got)
	}
}

func TestIsFinalDelivery(t *testing.T) {
	if IsFinalDelivery(delivered(4), 5) {
		t.Error("delivery 4/5 read as final")
	}
	if !IsFinalDelivery(delivered(5), 5) {
		t.Error("delivery 5/5 not read as final")
	}
	if !IsFinalDelivery(delivered(6), 5) {
		t.Error("delivery past MaxDeliver not read as final")
	}
	if IsFinalDelivery(delivered(1), 0) {
		t.Error("delivery read as final with MaxDeliver 0 (unlimited)")
	}
	if IsFinalDelivery(delivered(1), -1) {
		t.Error("delivery read as final with MaxDeliver -1 (unlimited)")
	}
}

// Package natspub is the shared JetStream publish core behind the typed job
// publishers (metajobs, prjobs, pushauthorjobs, donejobs, mirrorjobs): one
// producer span, the Nats-Msg-Id dedup header, a bounded pub-ack wait, and one
// INFO log per publish, so every job stream gets identical tracing,
// deduplication, and backpressure behavior. Each jobs package keeps its typed
// Publisher and owns the domain parts — subject, msg-id, payload, span/log
// attributes — and delegates the mechanics here.
package natspub

import (
	"context"
	"fmt"
	"log/slog"
	"time"

	"github.com/nats-io/nats.go"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"
	otelcodes "go.opentelemetry.io/otel/codes"
	"go.opentelemetry.io/otel/trace"

	"github.com/entirehq/mirror-pipeline/pkg/otelnats"
)

// MsgIDHeader is the JetStream deduplication header.
const MsgIDHeader = "Nats-Msg-Id"

// AckWait bounds the synchronous pub-ack wait (matches the nats.go default
// request wait). nats.Context alone waits on the CALLER's context — the
// callers' contexts are process-lifetime or per-message handler contexts, so a
// publish routed to a reconnecting NATS (or remote region) would sit in the
// client's reconnect buffer until the connection returned, stalling the serial
// consume loop. A bounded wait turns that into an error the caller can act on
// (consumer Nak → JetStream redelivery).
const AckWait = 5 * time.Second

// JetStreamPublisher is the subset of nats.JetStreamContext needed for publish.
type JetStreamPublisher interface {
	PublishMsg(m *nats.Msg, opts ...nats.PubOpt) (*nats.PubAck, error)
}

// Publication describes one job publish: where it goes, how it dedups, and how
// it is named in spans, logs, and errors.
type Publication struct {
	// Tracer names the otel tracer the producer span starts from.
	Tracer string
	// SpanName is the producer span name, e.g. "github_meta.publish".
	SpanName string
	// ErrKind labels failures: "marshal <ErrKind>: …" / "publish <ErrKind>: …".
	ErrKind string
	// LogMsg is the INFO message logged after a successful publish.
	LogMsg string

	// Subject is the fully-resolved NATS subject.
	Subject string
	// MsgID is the JetStream dedup id, set as the Nats-Msg-Id header.
	MsgID string
	// Marshal renders the job payload. It runs inside the producer span so a
	// marshal failure is recorded on it.
	Marshal func() ([]byte, error)

	// SpanAttrs are the domain span attributes, appended to the standard
	// messaging.* set.
	SpanAttrs []attribute.KeyValue
	// LogAttrs are the domain log attributes, logged ahead of the standard
	// subject/msg_id/sequence/duplicate set.
	LogAttrs []slog.Attr
}

// PlacementAttrs is the standard span-attribute pair for a placement-scoped
// subject (jurisdiction, cluster).
func PlacementAttrs(jurisdiction, cluster string) []attribute.KeyValue {
	return []attribute.KeyValue{
		attribute.String("entire.target_jurisdiction", jurisdiction),
		attribute.String("entire.target_cluster_id", cluster),
	}
}

// Publish runs one publication against js.
func Publish(ctx context.Context, js JetStreamPublisher, pub Publication) error {
	spanAttrs := append([]attribute.KeyValue{
		attribute.String("messaging.system", "nats"),
		attribute.String("messaging.operation.type", "publish"),
		attribute.String("messaging.destination.name", pub.Subject),
	}, pub.SpanAttrs...)

	ctx, span := otel.Tracer(pub.Tracer).Start(ctx, pub.SpanName,
		trace.WithSpanKind(trace.SpanKindProducer),
		trace.WithAttributes(spanAttrs...),
	)
	defer span.End()

	data, err := pub.Marshal()
	if err != nil {
		span.RecordError(err)
		span.SetStatus(otelcodes.Error, "marshal "+pub.ErrKind)
		return fmt.Errorf("marshal %s: %w", pub.ErrKind, err)
	}

	msg := &nats.Msg{
		Subject: pub.Subject,
		Data:    data,
		Header:  nats.Header{},
	}
	msg.Header.Set(MsgIDHeader, pub.MsgID)
	otelnats.Inject(ctx, msg)
	span.SetAttributes(attribute.String("messaging.message.id", pub.MsgID))

	pubCtx, cancel := context.WithTimeout(ctx, AckWait)
	defer cancel()
	ack, err := js.PublishMsg(msg, nats.Context(pubCtx))
	if err != nil {
		span.RecordError(err)
		span.SetStatus(otelcodes.Error, "nats publish")
		return fmt.Errorf("publish %s: %w", pub.ErrKind, err)
	}

	span.SetAttributes(
		attribute.Int64("messaging.nats.sequence", int64(ack.Sequence)),
		attribute.Bool("messaging.nats.duplicate", ack.Duplicate),
	)

	logAttrs := append(append([]slog.Attr{}, pub.LogAttrs...),
		slog.String("subject", pub.Subject),
		slog.String("msg_id", pub.MsgID),
		slog.Uint64("sequence", ack.Sequence),
		slog.Bool("duplicate", ack.Duplicate),
	)
	slog.LogAttrs(ctx, slog.LevelInfo, pub.LogMsg, logAttrs...)
	return nil
}

