package natspub

import (
	"context"
	"errors"
	"strings"
	"testing"

	"github.com/nats-io/nats.go"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"
	otelcodes "go.opentelemetry.io/otel/codes"
	"go.opentelemetry.io/otel/propagation"
	sdktrace "go.opentelemetry.io/otel/sdk/trace"
	"go.opentelemetry.io/otel/sdk/trace/tracetest"
	"go.opentelemetry.io/otel/trace"
)

type fakeJetStream struct {
	lastMsg *nats.Msg
	ack     *nats.PubAck
	err     error
	calls   int
}

func (f *fakeJetStream) PublishMsg(m *nats.Msg, _ ...nats.PubOpt) (*nats.PubAck, error) {
	f.calls++
	f.lastMsg = m
	if f.err != nil {
		return nil, f.err
	}
	if f.ack != nil {
		return f.ack, nil
	}
	return &nats.PubAck{Stream: "test_stream", Sequence: 1}, nil
}

// withTracing installs a recording tracer provider + W3C propagator and
// returns the recorder plus a restore func.
func withTracing(t *testing.T) *tracetest.SpanRecorder {
	t.Helper()
	prevTP := otel.GetTracerProvider()
	prevProp := otel.GetTextMapPropagator()

	rec := tracetest.NewSpanRecorder()
	tp := sdktrace.NewTracerProvider(sdktrace.WithSpanProcessor(rec))
	otel.SetTracerProvider(tp)
	otel.SetTextMapPropagator(propagation.NewCompositeTextMapPropagator(
		propagation.TraceContext{},
		propagation.Baggage{},
	))
	t.Cleanup(func() {
		_ = tp.Shutdown(context.Background())
		otel.SetTracerProvider(prevTP)
		otel.SetTextMapPropagator(prevProp)
	})
	return rec
}

func testPublication(js *fakeJetStream) Publication {
	return Publication{
		Tracer:   "natspub-test",
		SpanName: "test.publish",
		ErrKind:  "test job",
		LogMsg:   "Published test job",
		Subject:  "test.v1.us.cluster",
		MsgID:    "id-1",
		Marshal:  func() ([]byte, error) { return []byte(`{"ok":true}`), nil },
		SpanAttrs: append(PlacementAttrs("us", "cluster"),
			attribute.Int64("entire.github_repo_id", 42)),
	}
}

func TestPublishSetsSubjectMsgIDAndPayload(t *testing.T) {
	withTracing(t)

	js := &fakeJetStream{ack: &nats.PubAck{Sequence: 7, Duplicate: true}}
	if err := Publish(context.Background(), js, testPublication(js)); err != nil {
		t.Fatalf("Publish: %v", err)
	}

	if js.calls != 1 {
		t.Fatalf("calls = %d, want 1", js.calls)
	}
	if js.lastMsg.Subject != "test.v1.us.cluster" {
		t.Errorf("Subject = %q, want test.v1.us.cluster", js.lastMsg.Subject)
	}
	if got := js.lastMsg.Header.Get(MsgIDHeader); got != "id-1" {
		t.Errorf("Nats-Msg-Id = %q, want id-1", got)
	}
	if string(js.lastMsg.Data) != `{"ok":true}` {
		t.Errorf("Data = %q, want {\"ok\":true}", js.lastMsg.Data)
	}
	if js.lastMsg.Header.Get("traceparent") == "" {
		t.Error("traceparent header not injected")
	}
}

func TestPublishRecordsProducerSpan(t *testing.T) {
	rec := withTracing(t)

	js := &fakeJetStream{ack: &nats.PubAck{Sequence: 7, Duplicate: true}}
	if err := Publish(context.Background(), js, testPublication(js)); err != nil {
		t.Fatalf("Publish: %v", err)
	}

	spans := rec.Ended()
	if len(spans) != 1 {
		t.Fatalf("ended spans = %d, want 1", len(spans))
	}
	span := spans[0]
	if span.Name() != "test.publish" {
		t.Errorf("span name = %q, want test.publish", span.Name())
	}
	if span.SpanKind() != trace.SpanKindProducer {
		t.Errorf("span kind = %v, want producer", span.SpanKind())
	}

	got := map[attribute.Key]attribute.Value{}
	for _, kv := range span.Attributes() {
		got[kv.Key] = kv.Value
	}
	for key, want := range map[attribute.Key]string{
		"messaging.system":           "nats",
		"messaging.operation.type":   "publish",
		"messaging.destination.name": "test.v1.us.cluster",
		"messaging.message.id":       "id-1",
		"entire.target_jurisdiction": "us",
		"entire.target_cluster_id":   "cluster",
	} {
		if got[key].AsString() != want {
			t.Errorf("span attr %s = %q, want %q", key, got[key].AsString(), want)
		}
	}
	if got["messaging.nats.sequence"].AsInt64() != 7 {
		t.Errorf("sequence attr = %d, want 7", got["messaging.nats.sequence"].AsInt64())
	}
	if !got["messaging.nats.duplicate"].AsBool() {
		t.Error("duplicate attr = false, want true")
	}
}

func TestPublishMarshalError(t *testing.T) {
	rec := withTracing(t)

	js := &fakeJetStream{}
	pub := testPublication(js)
	pub.Marshal = func() ([]byte, error) { return nil, errors.New("boom") }

	err := Publish(context.Background(), js, pub)
	if err == nil {
		t.Fatal("Publish: want error")
	}
	if !strings.Contains(err.Error(), "marshal test job") {
		t.Errorf("error = %q, want marshal test job prefix", err)
	}
	if js.calls != 0 {
		t.Errorf("PublishMsg called %d times on marshal failure, want 0", js.calls)
	}

	spans := rec.Ended()
	if len(spans) != 1 || spans[0].Status().Code != otelcodes.Error {
		t.Error("marshal failure not recorded as span error")
	}
}

func TestPublishNATSError(t *testing.T) {
	rec := withTracing(t)

	js := &fakeJetStream{err: errors.New("nats down")}
	err := Publish(context.Background(), js, testPublication(js))
	if err == nil {
		t.Fatal("Publish: want error")
	}
	if !strings.Contains(err.Error(), "publish test job") || !strings.Contains(err.Error(), "nats down") {
		t.Errorf("error = %q, want wrapped publish test job error", err)
	}

	spans := rec.Ended()
	if len(spans) != 1 || spans[0].Status().Code != otelcodes.Error {
		t.Error("publish failure not recorded as span error")
	}
}

