38		Process(context.Background(), msg, testCfg, decode, handle, func(context.Context) { dropped = true })
39	
40		if gotEv != "decoded:payload" {
41			t.Errorf("handle got ev %q, want decoded:payload", gotEv)
42		}
43		if gotSpan == nil {
44			t.Error("handle got a nil span, want the live consumer span")
45		}
46		if gotMsg != msg {
47			t.Error("handle got a different msg than the one passed to Process")
48		}
49		if msg.Acked || msg.Termed || msg.Naks > 0 || len(msg.NakDelays) > 0 {
50			t.Error("Process disposed the message, want none (handle owns ack/nak)")
51		}
52		if dropped {
53			t.Error("onUndecodable called on a successful decode")
54		}
55	}
