577				if err := m.Ack(); err != nil {
578					t.Errorf("ack: %v", err)
579				}
580				got <- m
581			})
582		}()
583	
584		// Let at least one create attempt fail against the absent stream.
585		time.Sleep(60 * time.Millisecond)
586		if _, err := js.CreateStream(ctx, jetstream.StreamConfig{
587			Name: "late_v1", Subjects: []string{"late.>"},
588		}); err != nil {
589			t.Fatalf("create stream: %v", err)
590		}
591		if _, err := js.Publish(ctx, "late.repo", []byte("finally")); err != nil {
592			t.Fatalf("publish: %v", err)
593		}
594		select {
595		case m := <-got:
596			if string(m.Data()) != "finally" {
597				t.Errorf("payload = %q, want finally", m.Data())
598			}
599		case <-time.After(5 * time.Second):
600			t.Fatal("message did not arrive after the stream appeared")
601		}
602	
603		cancel()
604		select {
605		case err := <-done:
606			if err != nil {
607				t.Fatalf("Run returned %v on cancel, want nil", err)
608			}
609		case <-time.After(10 * time.Second):
610			t.Fatal("Run did not return after ctx cancel")
611		}
612	}
613	
614	// TestRunRecreatesAfterConsumerDeleted: deleting the durable on the server is
615	// a terminal error for the live consume loop (nats.go stops it and Closed
616	// fires); Run must notice and recreate rather than leaving the service
617	// running but deaf.
618	func TestRunRecreatesAfterConsumerDeleted(t *testing.T) {
619		compressRunRetries(t)
620		nc, js := runTestEnv(t)
621		ctx, cancel := context.WithCancel(context.Background())
622		defer cancel()
623		if _, err := js.CreateStream(ctx, jetstream.StreamConfig{
624			Name: "events_v1", Subjects: []string{"events.>"},
625		}); err != nil {
626			t.Fatalf("create stream: %v", err)
627		}
628	
629		got := make(chan string, 2)
630		done := make(chan error, 1)
631		cfg := Config{Stream: "events_v1", Durable: "recreate_durable", FilterSubject: "events.repo",
632			Name: "testconsumer", SpanName: "test.consume"}
633		go func() {
634			done <- Run(ctx, nc, cfg, func(m jetstream.Msg) {
635				if err := m.Ack(); err != nil {
636					t.Errorf("ack: %v", err)
637				}
638				got <- string(m.Data())
639			})
640		}()
641	
642		if _, err := js.Publish(ctx, "events.repo", []byte("one")); err != nil {
643			t.Fatalf("publish: %v", err)
644		}
645		select {
646		case m := <-got:
647			if m != "one" {
648				t.Fatalf("first delivery = %q, want one", m)
649			}
650		case <-time.After(5 * time.Second):
651			t.Fatal("first message did not arrive")
652		}
653	
654		if err := js.DeleteConsumer(ctx, "events_v1", "recreate_durable"); err != nil {
655			t.Fatalf("delete consumer: %v", err)
656		}
657		if _, err := js.Publish(ctx, "events.repo", []byte("two")); err != nil {
658			t.Fatalf("publish: %v", err)
659		}
660		// Deleting the durable erased its delivery cursor, so the recreated
661		// consumer legitimately redelivers "one" before "two"; wait for "two".
662		deadline := time.After(10 * time.Second)
663		for m := ""; m != "two"; {
664			select {
665			case m = <-got:
666			case <-deadline:
667				t.Fatal("message did not arrive after the consumer was deleted and recreated")
668			}
669		}
670	
671		cancel()
672		select {
673		case err := <-done:
674			if err != nil {
675				t.Fatalf("Run returned %v on cancel, want nil", err)
676			}
677		case <-time.After(10 * time.Second):
678			t.Fatal("Run did not return after ctx cancel")
679		}
680	}
681	
682	// runJetStreamServer starts an in-process JetStream-enabled NATS server on a
683	// random loopback port and returns its client URL.
684	func runJetStreamServer(t *testing.T) string {
685		t.Helper()
686		s, err := natsserver.NewServer(&natsserver.Options{
687			Host:      "127.0.0.1",
688			Port:      -1, // pick a free port
689			NoLog:     true,
690			NoSigs:    true,
691			JetStream: true,
692			StoreDir:  t.TempDir(),
693		})
694		if err != nil {
695			t.Fatalf("new embedded nats server: %v", err)
696		}
697		go s.Start()
698		if !s.ReadyForConnections(10 * time.Second) {
699			t.Fatal("embedded nats server not ready in time")
700		}
701		t.Cleanup(s.Shutdown)
702		return s.ClientURL()
703	}
704	
705	// TestStartDeliversToOnMsg drives the whole scaffold against an embedded
706	// JetStream server: Start creates the durable, a published message reaches
707	// onMsg, and cancelling ctx stops the runner.
708	func TestStartDeliversToOnMsg(t *testing.T) {
709		url := runJetStreamServer(t)
710		nc, err := nats.Connect(url)
711		if err != nil {
712			t.Fatalf("connect: %v", err)
713		}
714		t.Cleanup(nc.Close)
715	
716		js, err := jetstream.New(nc)
717		if err != nil {
718			t.Fatalf("jetstream.New: %v", err)
719		}
720		ctx, cancel := context.WithCancel(context.Background())
721		defer cancel()
722		if _, err := js.CreateStream(ctx, jetstream.StreamConfig{
723			Name: "events_v1", Subjects: []string{"events.>"},
724		}); err != nil {
725			t.Fatalf("create stream: %v", err)
726		}
727	
728		got := make(chan jetstream.Msg, 1)
729		run, err := Start(ctx, nc, Config{
730			Stream:        "events_v1",
731			Durable:       "test_durable",
732			FilterSubject: "events.repo",
733			Name:          "testconsumer",
734			SpanName:      "test.consume",
735		}, func(m jetstream.Msg) {
736			if err := m.Ack(); err != nil {
737				t.Errorf("ack: %v", err)
738			}
739			got <- m
740		})
741		if err != nil {
742			t.Fatalf("Start: %v", err)
743		}
744		defer run.Stop()
745	
746		if _, err := js.Publish(ctx, "events.repo", []byte("hello")); err != nil {
747			t.Fatalf("publish: %v", err)
748		}
749		select {
750		case m := <-got:
751			if string(m.Data()) != "hello" {
752				t.Errorf("payload = %q, want hello", m.Data())
753			}
754		case <-time.After(5 * time.Second):
755			t.Fatal("message did not reach onMsg")
756		}
757	}
