type fakeLegacyJS struct {
	last  *nats.Msg
	ack   *nats.PubAck
	err   error
	calls int
}

func (f *fakeLegacyJS) PublishMsg(m *nats.Msg, _ ...nats.PubOpt) (*nats.PubAck, error) {
	f.calls++
	f.last = m
	if f.err != nil {
		return nil, f.err
	}
	return f.ack, nil
}

var (
	_ jetstream.JetStream = (*fakeModernJS)(nil)
	_ LegacyJetStream     = (*fakeLegacyJS)(nil)
)

