	if tr == nil {
		tr = otel.Tracer("github.com/entireio/go-nuts/natsmsg")
	}
	name := cfg.operation
	var extra []attribute.KeyValue
	if cfg.operation == "" {
		name = "publish " + msg.Subject
	} else {
