28	func newStreamConn(t *testing.T) *nats.Conn {
29		t.Helper()
30		s, err := natsserver.NewServer(&natsserver.Options{
31			Host:      "127.0.0.1",
32			Port:      -1, // pick a free port
33			NoLog:     true,
34			NoSigs:    true,
35			JetStream: true,
36			StoreDir:  t.TempDir(),
37		})
38		if err != nil {
39			t.Fatalf("new embedded nats server: %v", err)
40		}
41		go s.Start()
42		if !s.ReadyForConnections(10 * time.Second) {
43			t.Fatal("embedded nats server not ready in time")
44		}
45		t.Cleanup(s.Shutdown)
46	
47		nc, err := nats.Connect(s.ClientURL())
48		if err != nil {
49			t.Fatalf("connect: %v", err)
50		}
